#include <avr/io.h>

/* The 595 is SPI mode 0. MOSI to DS, SCK to SH_CP, any GPIO to ST_CP. */
DDRB |= (1 << PB3) | (1 << PB5) | (1 << PB2);   /* MOSI, SCK, latch */
SPCR  = (1 << SPE) | (1 << MSTR);               /* enable, 1/4 clock */

void shift_out(uint8_t v) {
    SPDR = v;
    while (!(SPSR & (1 << SPIF))) { }           /* wait for the byte */
    PORTB |=  (1 << PB2);                       /* latch rising edge */
    PORTB &= ~(1 << PB2);
}
